"""Derive the test schema from Tableau's official reference definitions."""

import argparse
import concurrent.futures
import datetime
import hashlib
import html
import json
import pathlib
import re
import urllib.request

BASE = 'https://help.tableau.com/current/api/metadata_api/en-us/reference/'
OUTPUT = pathlib.Path(__file__).resolve().parent
BUILTIN_SCALARS = {'Boolean', 'Float', 'ID', 'Int', 'String'}


def digest(value):
    return hashlib.sha256(value).hexdigest()


def extract(raw, name):
    match = re.search(r'<code class="highlight">(.*?)</code>', raw.decode('utf-8'), re.S)
    if not match:
        raise ValueError('Missing schema definition: ' + name)
    definition = html.unescape(re.sub(r'<[^>]+>', '', match.group(1).replace('</li>', '\n'))).strip()
    # The legacy documentation uses commas between implemented interfaces.
    normalized = re.sub(r'(\bimplements\s+)([^{}]+)(\{)', lambda item: item.group(1) + item.group(2).replace(',', ' & ') + item.group(3), definition)
    # Comments contain descriptions, not schema declarations.
    compact = '\n'.join(line.strip() for line in normalized.splitlines() if line.strip() and not line.lstrip().startswith('#'))
    scalar = re.fullmatch(r'scalar (\w+)', compact)
    if scalar and scalar.group(1) in BUILTIN_SCALARS:
        compact = ''
    return definition, compact


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source-cache', type=pathlib.Path, help='Reuse a directory containing index.html and official page captures.')
    args = parser.parse_args()

    def read(name):
        if args.source_cache is not None:
            return (args.source_cache / name).read_bytes()
        with urllib.request.urlopen(BASE + ('' if name == 'index.html' else name), timeout=30) as response:
            return response.read()

    index = read('index.html')
    names = sorted(set(re.findall(r'href="([a-z_0-9]+\.doc\.html)"', index.decode('utf-8'))))

    def process(name):
        raw = read(name)
        definition, compact = extract(raw, name)
        return {'url': BASE + name, 'html_sha256': digest(raw), 'definition_sha256': digest(definition.encode('utf-8'))}, compact

    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        records = list(pool.map(process, names))
    content = '# Generated by generate-schema.py from official Tableau documentation.\n' + '\n\n'.join(code for _, code in records if code) + '\n'
    schema_path = OUTPUT / 'tableau-schema.graphql'
    schema_path.write_text(content, encoding='utf-8', newline='\n')
    generated_at = datetime.datetime.now(datetime.timezone.utc).isoformat()
    retrieved_at = generated_at
    if args.source_cache is not None:
        source_manifest = args.source_cache / 'manifest.json'
        retrieved_at = json.loads(source_manifest.read_text(encoding='utf-8')).get('retrieved_at') if source_manifest.exists() else None
    provenance = {
        'source': BASE,
        'retrieved_at': retrieved_at,
        'generated_at': generated_at,
        'index_sha256': digest(index),
        'schema_sha256': digest(content.encode('utf-8')),
        'transformations': [
            'Extract code.highlight, replace closing li with newline, remove presentation HTML tags, and decode HTML entities.',
            'Replace commas with ampersands only in implements clauses for standard GraphQL syntax.',
            'Remove comments and empty lines; trim line indentation.',
            'Omit documented Boolean, Float, ID, Int, and String scalar declarations supplied by the GraphQL parser Prelude.',
            'Concatenate complete remaining definitions in reference filename order.',
        ],
        'pages': [record for record, _ in records],
    }
    (OUTPUT / 'tableau-schema-provenance.json').write_text(json.dumps(provenance, indent=2) + '\n', encoding='utf-8', newline='\n')
    print(json.dumps({'definitions': len(records), 'schema_bytes': len(content.encode('utf-8')), 'schema_sha256': provenance['schema_sha256']}))


if __name__ == '__main__':
    main()
